package lyrics

import (
	"strings"
	"sync"
	"unicode"
	"unicode/utf8"
)

// Traditional and simplified Chinese write many names differently: a library
// tagged "陳奕迅 – 婚禮的祝福" and a Chinese service that has "陈奕迅 – 婚礼的祝福"
// are the same recording. simplifiedHan brings the traditional characters to
// their simplified form, from the Unicode Han Database (hanfold_table.go,
// generated by scripts/gen_hanfold.py). It only changes Han characters with a
// single simplified form; kana, hangul and everything else are kept as they are.

var (
	hanOnce sync.Once
	hanMap  map[rune]rune
)

func hanTable() map[rune]rune {
	hanOnce.Do(func() {
		hanMap = make(map[rune]rune, utf8.RuneCountInString(hanSimplified)/2)
		var from rune = -1
		for _, r := range hanSimplified {
			if from < 0 {
				from = r
				continue
			}
			hanMap[from] = r
			from = -1
		}
	})
	return hanMap
}

// simplifiedHan returns s with traditional Chinese characters in their
// simplified form. Text without Han characters is returned as it is.
func simplifiedHan(s string) string {
	if !strings.ContainsFunc(s, func(r rune) bool { return unicode.Is(unicode.Han, r) }) {
		return s
	}
	table := hanTable()
	return strings.Map(func(r rune) rune {
		if to, ok := table[r]; ok {
			return to
		}
		return r
	}, s)
}
